import React, { useState, useEffect } from 'react';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  // 🟢 NEW ACTIVE SUB-TAB STATE
  const [subTab, setSubTab] = useState('forum'); // 'forum' அல்லது 'lessons'

  // --- 💬 FORUM SPACE STATES & LOGIC (100% OLD CODE PRESERVED) ---
  const [messages, setMessages] = useState([
    { id: 1, sender: `${userName || 'Buddhika Darshani'} (Teacher)`, text: 'ළමයි, Lesson 01 එකේ ගණිත ගැටළු වල මොනවා හරි නොවැටහෙන තැන් තියෙනවද?', isMe: true },
    { id: 2, sender: 'Amali Perera (Student)', text: 'නැහැ ටීචර්, වීඩියෝ එක බැලුවට පස්සේ ඔක්කොම ලස්සනට තේරුණා.', isMe: false }
  ]);
  const [typeText, setTypeText] = useState('');

  const handleSend = (e) => {
    e.preventDefault();
    if (!typeText.trim()) return;
    
    const newMsg = {
      id: Date.now(),
      sender: `${userName || 'Buddhika Darshani'} (Teacher)`,
      text: typeText,
      isMe: true
    };
    setMessages([...messages, newMsg]);
    setTypeText('');
    alert("💬 ඔබගේ පණිවිඩය සාර්ථකව සාකච්ඡා මණ්ඩපයට (Student Forum) එක් කරන ලදි!");
  };

  // --- 🧩 LESSON ACTIVITIES MANAGER STATES & LOGIC ---
  const [activities, setActivities] = useState([]);
  const [selectedLesson, setSelectedLesson] = useState('Lesson 01');
  const [activityType, setActivityType] = useState('BLANK');
  const [questionText, setQuestionText] = useState('');
  const [correctAnswer, setCorrectAnswer] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('aura_lesson_activities');
    if (saved) {
      setActivities(JSON.parse(saved));
    } else {
      const defaultData = [
        { id: 1, lesson: 'Lesson 01', type: 'BLANK', question: '1, 4, 9, 16, ... යන සමචතුරශ්‍ර සංඛ්‍යා රටාවේ 5 වන පදය වනුයේ ______ වේ.', correct: '25' },
        { id: 2, lesson: 'Lesson 01', type: 'BLANK', question: '2, 4, 6, 8, ... යන ඉරට්ටේ සංඛ්‍යා රටාවේ n වන පොදු පදය වීජීයව දැක්වූ විට ______ වේ.', correct: '2n' },
        { id: 3, lesson: 'Lesson 01', type: 'MCQ', question: '3, 5, 7, 9, 11, ... යන සංඛ්‍යා රටාවේ පොදු පදය කුමක්ද?', options: { A: 'n + 2', B: '2n - 1', C: '2n + 1', D: '3n' }, correct: 'C' }
      ];
      setActivities(defaultData);
      localStorage.setItem('aura_lesson_activities', JSON.stringify(defaultData));
    }
  }, []);

  const handleSaveActivity = (e) => {
    e.preventDefault();
    const newActivity = {
      id: Date.now(),
      lesson: selectedLesson,
      type: activityType,
      question: questionText,
      correct: correctAnswer
    };
    if (activityType === 'MCQ') {
      newActivity.options = { A: optA, B: optB, C: optC, D: optD };
    }
    const updatedList = [...activities, newActivity];
    setActivities(updatedList);
    localStorage.setItem('aura_lesson_activities', JSON.stringify(updatedList));

    setQuestionText(''); setCorrectAnswer('');
    setOptA(''); setOptB(''); setOptC(''); setOptD('');
    alert("✅ Lesson Activity එක සාර්ථකව පද්ධතියට ඇතුළත් කරන ලදි!");
  };

  const handleDeleteActivity = (id) => {
    if (window.confirm("මෙම ක්‍රියාකාරකම සදහටම මකා දැමීමට අවශ්‍යද?")) {
      const updatedList = activities.filter(act => act.id !== id);
      setActivities(updatedList);
      localStorage.setItem('aura_lesson_activities', JSON.stringify(updatedList));
    }
  };

  const filteredActivities = activities.filter(act => act.lesson === selectedLesson);

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      {/* GLOBAL TOP TOGGLE TABS */}
      <div style={{ display: 'flex', gap: '10px', borderBottom: '2px solid #e2e8f0', paddingBottom: '10px' }}>
        <button 
          onClick={() => setSubTab('forum')} 
          style={{
            padding: '10px 20px', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13.5px',
            backgroundColor: subTab === 'forum' ? '#145c2e' : '#f1f5f9',
            color: subTab === 'forum' ? 'white' : '#475569', transition: '0.2s'
          }}
        >
          💬 Class Forum Space
        </button>
        <button 
          onClick={() => setSubTab('lessons')} 
          style={{
            padding: '10px 20px', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13.5px',
            backgroundColor: subTab === 'lessons' ? '#6b21a8' : '#f1f5f9',
            color: subTab === 'lessons' ? 'white' : '#475569', transition: '0.2s'
          }}
        >
          🧩 Lesson Activities Manager
        </button>
      </div>

      {/* 🟢 RENDER PART 1: CHAT FORUM SPACE (100% PRESERVED FROM USER VERSION) */}
      {subTab === 'forum' && (
        <>
          <div>
            <h2 style={{ color: '#1e293b', margin: 0, display: 'flex', alignItems: 'center', gap: '10px' }}>
              💬 Class Forum Space & Discussion Control
            </h2>
            <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
              ගුරුවරුන් සහ සිසුන් අතර සජීවීව විෂය කරුණු ගැටළු සාකච්ඡා කිරීමේ නිල පුවරුව.
            </p>
          </div>

          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <h3 style={{ margin: 0, fontSize: '15px', color: '#1e293b', fontWeight: 'bold' }}>🗣️ Dynamic Active Stream ({teachingSubject || 'Mathematics'})</h3>
              <span style={{ fontSize: '11px', backgroundColor: '#dcfce7', color: '#16a34a', padding: '4px 10px', borderRadius: '20px', fontWeight: 'bold' }}>🟢 Portal Online</span>
            </div>

            <div style={{ border: '1px solid #cbd5e1', borderRadius: '12px', height: '280px', backgroundColor: '#f8fafc', padding: '20px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' }}>
              {messages.map((m) => (
                <div 
                  key={m.id} 
                  style={{ 
                    alignSelf: m.isMe ? 'flex-start' : 'flex-end', 
                    backgroundColor: m.isMe ? '#e2e8f0' : '#dcfce7', 
                    padding: '12px 16px', 
                    borderRadius: '12px', 
                    maxWidth: '70%', 
                    fontSize: '13.5px',
                    boxShadow: '0 2px 5px rgba(0,0,0,0.02)'
                  }}
                >
                  <strong style={{ display: 'block', fontSize: '11px', color: m.isMe ? '#475569' : '#16a34a', marginBottom: '4px' }}>
                    {m.sender}
                  </strong>
                  {m.text}
                </div>
              ))}
            </div>

            <form onSubmit={handleSend} style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
              <input 
                type="text" 
                placeholder="Type your official announcement or answer here..." 
                value={typeText}
                onChange={e => setTypeText(e.target.value)}
                style={{ flex: 1, padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13.5px', outline: 'none', backgroundColor: '#f8fafc' }} 
              />
              <button type="submit" style={{ backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '0 25px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13.5px' }}>
                Broadcast 🚀
              </button>
            </form>
          </div>
        </>
      )}

      {/* 🟢 RENDER PART 2: DYNAMIC LESSON ACTIVITIES INTEGRATION AREA */}
      {subTab === 'lessons' && (
        <>
          <div>
            <h2 style={{ color: '#1e293b', margin: 0 }}>🧩 Lesson Interactive Activities Manager</h2>
            <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
              පාඩම් නිම වූ පසු සිසුන්ට ලබා දෙන හිස්තැන් පිරවීමේ (Fill in the blanks) සහ කෙටි ප්‍රශ්න සකස් කිරීමේ පුවරුව.
            </p>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.3fr', gap: '25px', alignItems: 'start' }}>
            
            <div style={customStyles.card('#6b21a8')}>
              <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b' }}>➕ Create Lesson Activity</h3>
              <form onSubmit={handleSaveActivity} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div>
                  <label style={customStyles.label}>Target Lesson</label>
                  <select value={selectedLesson} onChange={e => setSelectedLesson(e.target.value)} style={customStyles.fullInput}>
                    <option value="Lesson 01">Lesson 01 - සංඛ්‍යා රටා</option>
                    <option value="Lesson 02">Lesson 02 - සරල සමීකරණ</option>
                  </select>
                </div>
                <div>
                  <label style={customStyles.label}>Question Model</label>
                  <select value={activityType} onChange={e => setActivityType(e.target.value)} style={customStyles.fullInput}>
                    <option value="BLANK">✍️ Fill in the Blanks (හිස්තැන් පුරවන්න)</option>
                    <option value="MCQ">🔘 Multiple Choice Question (බහුවරණ)</option>
                  </select>
                </div>
                <div>
                  <label style={customStyles.label}>Question Setup (Use ______ for the blank space)</label>
                  <textarea placeholder="e.g., 2, 4, 6 හි ඊළඟ පදය ______ වේ." value={questionText} onChange={e => setQuestionText(e.target.value)} required style={customStyles.textArea} />
                </div>

                {activityType === 'MCQ' && (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '10px', backgroundColor: '#f8fafc', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                    <input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={customStyles.fullInput} />
                    <input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={customStyles.fullInput} />
                    <input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} style={customStyles.fullInput} />
                    <input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} style={customStyles.fullInput} />
                  </div>
                )}
                <div>
                  <label style={customStyles.label}>Correct Evaluation Answer</label>
                  <input type="text" placeholder="Correct Answer Key" value={correctAnswer} onChange={e => setCorrectAnswer(e.target.value)} required style={customStyles.fullInput} />
                </div>
                <button type="submit" style={{ ...customStyles.btn, backgroundColor: '#6b21a8' }}>Deploy Activity Node 🚀</button>
              </form>
            </div>

            <div style={customStyles.card('#475569')}>
              <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b' }}>📚 Active Activities Cluster ({filteredActivities.length})</h3>
              <div style={{ marginBottom: '15px' }}>
                <select value={selectedLesson} onChange={e => setSelectedLesson(e.target.value)} style={customStyles.fullInput}>
                  <option value="Lesson 01">Showing: Lesson 01 - සංඛ්‍යා රටා</option>
                  <option value="Lesson 02">Showing: Lesson 02 - සරල සමීකරණ</option>
                </select>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '350px', overflowY: 'auto' }}>
                {filteredActivities.map((act, index) => (
                  <div key={act.id} style={customStyles.activityItem}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '5px' }}>
                      <span style={{ color: '#64748b', fontWeight: 'bold' }}>Activity #{index + 1}</span>
                      <span style={{ color: act.type === 'BLANK' ? '#6b21a8' : '#2563eb', backgroundColor: act.type === 'BLANK' ? '#f3e8ff' : '#dbeafe', padding: '2px 8px', borderRadius: '4px', fontWeight: 'bold' }}>{act.type}</span>
                    </div>
                    <p style={{ margin: '5px 0', fontSize: '13px', fontWeight: '600', color: '#1e293b' }}>{act.question}</p>
                    {act.type === 'MCQ' && act.options && (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '5px', fontSize: '12px', color: '#64748b', paddingLeft: '5px' }}>
                        <div>A) {act.options.A}</div><div>B) {act.options.B}</div>
                        <div>C) {act.options.C}</div><div>D) {act.options.D}</div>
                      </div>
                    )}
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '8px', borderTop: '1px dashed #e2e8f0', paddingTop: '6px', fontSize: '12px' }}>
                      <span style={{ color: '#16a34a', fontWeight: 'bold' }}>🔑 Key: {act.correct}</span>
                      <button type="button" onClick={() => handleDeleteActivity(act.id)} style={customStyles.deleteBtn}>🗑️ Delete</button>
                    </div>
                  </div>
                ))}
                {filteredActivities.length === 0 && <p style={{ color: '#94a3b8', fontStyle: 'italic', fontSize: '12px', textAlign: 'center' }}>📭 මෙම පාඩමට අදාළ ප්‍රශ්න නැත.</p>}
              </div>
            </div>

          </div>
        </>
      )}

    </div>
  );
}

const customStyles = {
  card: (color) => ({ backgroundColor: 'white', padding: '20px', borderRadius: '15px', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column', borderLeft: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }),
  label: { display: 'block', fontSize: '11.5px', fontWeight: 'bold', color: '#475569', marginBottom: '4px' },
  fullInput: { width: '100%', padding: '9px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13px', boxSizing: 'border-box', outline: 'none', marginBottom: '4px' },
  textArea: { width: '100%', padding: '9px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13px', boxSizing: 'border-box', height: '55px', resize: 'none', outline: 'none' },
  btn: { color: 'white', border: 'none', padding: '10px 18px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13px', cursor: 'pointer', marginTop: '4px' },
  activityItem: { backgroundColor: '#f8fafc', padding: '12px', borderRadius: '10px', border: '1px solid #e2e8f0' },
  deleteBtn: { padding: '3px 8px', border: 'none', backgroundColor: '#fee2e2', color: '#b91c1c', borderRadius: '4px', cursor: 'pointer', fontSize: '11px', fontWeight: 'bold' }
};
